for (cnty in county_names) {   sch_in_c <- locations_sim[parent_id == cnty, loc_id]   sch_pars <- paste0("off_layer[", match(sch_in_c, non_root_locs), "]")   sch_arr <- off_layer_arr[, , sch_pars, drop = FALSE]    sch_chain_meds <- rbindlist(lapply(sch_pars, function(p) {     data.table(       parameter = p,       Chain = factor(seq_len(dim(sch_arr)[2])),       med_val = apply(sch_arr[, , p, drop = FALSE], 2, median)     )   }))    obs_sch <- obs[loc_id %in% sch_in_c]   obs_sch[, mu := {     c_off <- unname(off_cnty[parent_id])     s_off <- unname(off_sch[loc_id])     phi_s <- plogis(qlogis(phi_st[cohort]) + c_off + s_off)     (1 - phi_s) * cov[5, 2]   }, by = .(loc_id, parent_id)]   obs_sch[, p_adj := (positive + 0.5) / (sample_n + 1.0)]   obs_sch[, delta_cov := qlogis(p_adj) - qlogis(mu)]    sch_errs <- obs_sch[, .(expected_delta_err = -mean(delta_cov)), by = .(loc_id)]   sch_post_meds <- apply(sch_arr, 3, median)    sch_ref <- data.frame(     parameter = sch_pars,     loc_id = sch_in_c,     true_val = unname(latent_params_sim$off_sch[sch_in_c]),     post_med = unname(sch_post_meds[sch_pars]),     label = sprintf(       "True~delta == %.2f",       latent_params_sim$off_sch[sch_in_c]     )   )   sch_ref <- merge(sch_ref, sch_errs, by = "loc_id")    err_scale <- 2.5   sch_ref$red_arrow_x <- 0   sch_ref$red_arrow_yend <- sch_ref$true_val + err_scale * sch_ref$expected_delta_err   sch_ref$blue_arrow_x <- 500   sch_ref$blue_arrow_yend <- sch_ref$post_med    p <- bayesplot::mcmc_trace(     sch_arr,     facet_args = list(       ncol = 4,       scales = "fixed",       labeller = ggplot2::as_labeller(setNames(sch_in_c, sch_pars))     )   ) +     geom_hline(       data = sch_chain_meds,       aes(yintercept = med_val, color = Chain),       linetype = "solid",       linewidth = 0.5,       alpha = 0.8     ) +     geom_hline(       data = sch_ref,       aes(yintercept = true_val),       color = "firebrick",       linetype = "dashed",       linewidth = 0.8     ) +     geom_segment(       data = sch_ref,       aes(x = red_arrow_x, xend = red_arrow_x, y = true_val, yend = red_arrow_yend),       arrow = arrow(length = unit(0.04, "inches"), type = "closed"),       color = "firebrick",       linewidth = 0.7     ) +     geom_segment(       data = sch_ref,       aes(x = blue_arrow_x, xend = blue_arrow_x, y = true_val, yend = blue_arrow_yend),       arrow = arrow(length = unit(0.04, "inches"), type = "closed"),       color = "royalblue",       linewidth = 0.7     ) +     geom_label(       data = sch_ref,       aes(x = 50, y = true_val, label = label),       parse = TRUE,       color = "firebrick",       fill = ggplot2::alpha("white", 0.75),       linewidth = NA,       vjust = -0.3,       hjust = 0,       size = 2.6     ) +     labs(title = paste0(cnty, " County — School Location Offsets")) +     theme_bw() +     theme(       legend.position = "none",       plot.margin = margin(t = 5, b = 20, unit = "pt")     )    print(p)   cat("

